/**
 * Collection page — renders the private RobinLab vault (Hugging Face bucket).
 *
 * The browser never sees the Hugging Face token: every request goes to the
 * local proxy endpoint (`/api/collection/*`), which is implemented by
 * `functions/api/collection/[[path]].js` in production and by `dev_server.py`
 * locally.
 *
 * Every bucket folder is presented as a "pack": its own titled section with the
 * images inside shown at their real aspect ratio (never cropped). Grid cards use
 * the WebP previews generated by `tools/make_thumbs.py`; the lightbox loads the
 * full-resolution original.
 *
 * Only images appear here — .pptx decks live on /presentations.
 *
 * Visitors can share one image with a signed link (`POST /api/collection/share`).
 * The token is HMAC-signed and carries its own expiry, so a link stops working
 * after 30 minutes; the server refuses expired tokens with `410`.
 *
 * Downloads are intentionally disabled — the UI is view-only for now.
 */
(() => {
  "use strict";

  const LIST_ENDPOINT = "/api/collection/files";
  const SHARE_ENDPOINT = "/api/collection/share";

  const el = {
    search: document.getElementById("col-search"),
    sort: document.getElementById("col-sort"),
    viewBtns: document.querySelectorAll(".col-view-btn"),
    folders: document.getElementById("col-folders"),
    stats: document.getElementById("col-stats"),
    packs: document.getElementById("col-packs"),
    state: document.getElementById("col-state"),
    year: document.getElementById("year"),
    lightbox: document.getElementById("lightbox"),
    lbImg: document.getElementById("lb-img"),
    lbName: document.getElementById("lb-name"),
    lbMeta: document.getElementById("lb-meta"),
    lbCounter: document.getElementById("lb-counter"),
    lbClose: document.getElementById("lb-close"),
    lbPrev: document.getElementById("lb-prev"),
    lbNext: document.getElementById("lb-next"),
    lbShare: document.getElementById("lb-share"),
    toast: document.getElementById("toast"),
    tabs: document.querySelectorAll(".col-tab"),
    packList: document.getElementById("col-packlist"),
    tabPacksCount: document.getElementById("col-tab-packs-count"),
    tabImagesCount: document.getElementById("col-tab-images-count"),
    toolbar: document.querySelector(".col-toolbar"),
  };

  // How folders become packs.
  //  "nested": only a folder that has subfolders is a pack. Every image is filed
  //            under its nearest such folder; the rest (folders without subfolders,
  //            loose images) is one "General" pack.
  //  "all":    every folder that holds images is its own pack, at any depth.
  // Change DEFAULT_PACK_MODE to switch modes, or try one ad hoc
  // with /collection?packs=all (and ?packs=nested to compare).
  const DEFAULT_PACK_MODE = "all";
  const modeParam = new URLSearchParams(window.location.search).get("packs");
  const PACK_MODE = modeParam === "all" || modeParam === "nested" ? modeParam : DEFAULT_PACK_MODE;

  const MANIFEST_KEY = "rl-collection-manifest-v1";
  const VIEW_KEY = "rl-collection-view";
  // /certificates reuses this script; certificates never appear in the collection.
  const CERT_SCOPE = document.body.dataset.scope === "certificates";
  const isCertificate = (file) => /certificate/i.test(file.folder || "");
  const EAGER_COUNT = 12;

  // Browsers' native lazy-loading waits until an image is a viewport or two
  // away, which on a proxied grid shows blank cards while scrolling. Starting
  // 1500px ahead keeps the images ready before they are seen.
  const imageObserver =
    "IntersectionObserver" in window
      ? new IntersectionObserver(
          (entries) => {
            for (const entry of entries) {
              if (!entry.isIntersecting) continue;
              const img = entry.target;
              imageObserver.unobserve(img);
              img.src = img.dataset.src;
            }
          },
          { rootMargin: "1500px 0px" },
        )
      : null;

  let allFiles = [];
  let packs = new Map();
  let visible = [];
  let activeFolder = "";
  let query = "";
  let sort = "name";
  let lbPos = -1;
  let lastFocused = null;
  let lbDims = "";
  // Set only while the lightbox was opened from a shared link: drives the
  // "N min left" note and stops when the viewer closes.
  let shareSession = null;
  let shareTimer = 0;
  let toastTimer = 0;
  let tabChosen = false;
  let activeExact = false;
  let packBase = ""; // lone container folder (e.g. wallpapers) — its own loose images are "General"
  let parents = new Set(); // every folder that has at least one subfolder below it

  /* ------------------------------------------------------------------ */
  /* Helpers                                                             */
  /* ------------------------------------------------------------------ */

  function formatBytes(bytes) {
    if (!bytes) return "0 B";
    const units = ["B", "KB", "MB", "GB"];
    const i = Math.min(Math.floor(Math.log(bytes) / Math.log(1024)), units.length - 1);
    const value = bytes / 1024 ** i;
    const rounded = i === 0 || value >= 10 ? Math.round(value) : value.toFixed(1);
    return `${rounded} ${units[i]}`;
  }

  function humanName(file) {
    // The real file name, extension included — never the folder path.
    return file.name;
  }

  function folderLabel(file) {
    return file.folder || "General";
  }

  // A folder is a pack. Keep the bucket's own name, just make it readable.
  function packName(folder) {
    if (!folder) return "General";
    return folder
      .split("/")
      .map((part) => part.replace(/[-_]+/g, " ").replace(/^./, (c) => c.toUpperCase()))
      .join(" / ");
  }

  const relToBase = (folder) =>
    packBase && folder.startsWith(packBase + "/") ? folder.slice(packBase.length + 1) : folder === packBase ? "" : folder;

  // Title of a pack key. In "all" mode a folder that also has subfolders calls its
  // own loose images "<folder> / General".
  function packTitle(key) {
    const rel = relToBase(key);
    if (!rel) return "General";
    const name = packName(rel);
    return PACK_MODE === "all" && parents.has(key) ? `${name} / General` : name;
  }

  function isPreviewable(file) {
    return typeof file.previewable === "boolean"
      ? file.previewable
      : /^image\//.test(file.contentType || "");
  }

  function showState(kind, title, detail) {
    el.state.hidden = false;
    el.state.className = `col-state col-state-${kind}`;
    el.state.textContent = "";

    const heading = document.createElement("p");
    heading.className = "col-state-title";
    heading.textContent = title;
    el.state.appendChild(heading);

    if (detail) {
      const text = document.createElement("p");
      text.className = "col-state-detail";
      text.textContent = detail;
      el.state.appendChild(text);
    }
  }

  function hideState() {
    el.state.hidden = true;
    el.state.textContent = "";
  }

  /** Small transient message at the bottom of the screen. */
  function toast(message, kind = "ok", duration = 3600) {
    if (!el.toast) return;
    el.toast.textContent = message;
    el.toast.className = `toast toast-${kind}`;
    el.toast.hidden = false;
    clearTimeout(toastTimer);
    toastTimer = window.setTimeout(() => {
      el.toast.hidden = true;
    }, duration);
  }

  /** Clipboard first, legacy textarea fallback for browsers that block it. */
  async function copyText(text) {
    if (navigator.clipboard && typeof navigator.clipboard.writeText === "function") {
      try {
        await navigator.clipboard.writeText(text);
        return true;
      } catch {
        // fall through to execCommand
      }
    }
    try {
      const area = document.createElement("textarea");
      area.value = text;
      area.setAttribute("readonly", "");
      area.style.position = "fixed";
      area.style.top = "-1000px";
      area.style.opacity = "0";
      document.body.appendChild(area);
      area.select();
      const ok = document.execCommand("copy");
      area.remove();
      return ok;
    } catch {
      return false;
    }
  }

  /* ------------------------------------------------------------------ */
  /* Filtering + sorting                                                 */
  /* ------------------------------------------------------------------ */

  const sorters = {
    name: (a, b) => a.name.localeCompare(b.name, undefined, { numeric: true, sensitivity: "base" }),
    recent: (a, b) => Date.parse(b.uploadedAt || 0) - Date.parse(a.uploadedAt || 0) || a.name.localeCompare(b.name),
    largest: (a, b) => b.size - a.size,
    smallest: (a, b) => a.size - b.size,
  };

  function matchesQuery(file) {
    if (!query) return true;
    return file.name.toLowerCase().includes(query) || file.path.toLowerCase().includes(query);
  }

  /* ------------------------------------------------------------------ */
  /* Rendering                                                           */
  /* ------------------------------------------------------------------ */

  function renderChips() {
    el.folders.textContent = "";

    const entries = [["", allFiles.length], ...sortedPackKeys().map((key) => [key, packs.get(key).length])];

    for (const [folder, count] of entries) {
      const isAll = folder === "";

      const chip = document.createElement("button");
      chip.type = "button";
      chip.className = "col-chip";
      chip.dataset.folder = folder;
      chip.setAttribute("aria-pressed", String(folder === activeFolder));
      chip.textContent = isAll ? "Everything" : packTitle(folder);
      chip.title = isAll ? "Show every pack" : `Show only ${packTitle(folder)}`;

      const badge = document.createElement("span");
      badge.className = "col-chip-count";
      badge.textContent = String(count);
      chip.appendChild(badge);

      chip.addEventListener("click", () => {
        activeFolder = folder;
        activeExact = !isAll;
        syncChips();
        render();
      });

      el.folders.appendChild(chip);
    }
  }

  /** Open the images view scoped to one folder (exact = only files directly in it). */
  function openScope(folder, exact) {
    activeFolder = folder;
    activeExact = exact;
    syncChips();
    setTab("images");
    window.scrollTo({ top: 0 });
  }

  function syncChips() {
    for (const chip of el.folders.querySelectorAll(".col-chip")) {
      const f = chip.dataset.folder;
      const on = f === "" ? !activeFolder && !activeExact : f === activeFolder;
      chip.setAttribute("aria-pressed", String(on));
    }
  }

  const inFolder = (file, folder) => (file.folder || "") === folder;
  const underFolder = (file, folder) => (folder ? (file.folder || "").startsWith(folder + "/") : !!file.folder);

  function packCard(title, files, onOpen, hint) {
    const bytes = files.reduce((sum, file) => sum + file.size, 0);

    const card = document.createElement("button");
    card.type = "button";
    card.className = "col-packcard";
    card.title = hint;

    const cover = document.createElement("span");
    cover.className = "col-packcover";
    const covers = files.slice().sort(sorters.name).slice(0, 3);
    const shown = covers.length < 3 ? covers.slice(0, 1) : covers;
    if (shown.length < 3) cover.classList.add("is-single");
    for (const file of shown) {
      const img = document.createElement("img");
      img.alt = "";
      img.loading = "lazy";
      img.decoding = "async";
      img.draggable = false;
      img.src = file.thumbUrl || file.url;
      cover.appendChild(img);
    }

    const info = document.createElement("span");
    info.className = "col-packinfo";
    const name = document.createElement("span");
    name.className = "col-packname";
    name.textContent = title;
    const meta = document.createElement("span");
    meta.className = "col-packmeta";
    meta.textContent = `${files.length} ${files.length === 1 ? "image" : "images"} · ${formatBytes(bytes)}`;
    info.append(name, meta);

    card.append(cover, info);
    card.addEventListener("click", onOpen);
    return card;
  }

  /** Pack keys in display order: the container's General first, then by title. */
  function sortedPackKeys() {
    return [...packs.keys()].sort((a, b) => {
      if (a === packBase) return -1;
      if (b === packBase) return 1;
      return packTitle(a).localeCompare(packTitle(b), undefined, { numeric: true, sensitivity: "base" });
    });
  }

  /**
   * "all" mode on the Packs tab: the folder tree, to any depth. A folder with
   * subfolders is a group (heading + its own General card + its leaf folders as
   * cards) and each subfolder that has subfolders of its own nests inside it.
   */
  function buildPackTree() {
    const folders = new Set([...packs.keys(), ...parents]);
    const parentOf = (f) => (f.includes("/") ? f.slice(0, f.lastIndexOf("/")) : "");
    const lastOf = (f) => f.slice(f.lastIndexOf("/") + 1);
    const inside = (f) => (packBase ? f.startsWith(packBase + "/") : !!f);
    const byName = (a, b) => lastOf(a).localeCompare(lastOf(b), undefined, { numeric: true, sensitivity: "base" });
    const countUnder = (f) =>
      [...packs.entries()].reduce((n, [key, list]) => (key === f || key.startsWith(f + "/") ? n + list.length : n), 0);

    const group = (folder, isRoot) => {
      const wrap = document.createElement("section");
      wrap.className = "col-packgroup";

      if (!isRoot) {
        const head = document.createElement("div");
        head.className = "col-packgroup-head";
        const title = document.createElement("h3");
        title.textContent = packName(lastOf(folder));
        const meta = document.createElement("span");
        const n = countUnder(folder);
        meta.textContent = `${n} ${n === 1 ? "image" : "images"}`;
        head.append(title, meta);
        wrap.appendChild(head);
      }

      const grid = document.createElement("div");
      grid.className = "col-packgrid";
      const nested = [];
      if (packs.has(folder)) {
        const title = isRoot || parents.has(folder) ? "General" : packName(lastOf(folder));
        grid.appendChild(packCard(title, packs.get(folder), () => openScope(folder, true), `Open ${packTitle(folder)}`));
      }
      const kids = [...folders].filter((f) => f && f !== folder && inside(f) && parentOf(f) === folder).sort(byName);
      for (const kid of kids) {
        if (parents.has(kid)) nested.push(kid);
        else grid.appendChild(packCard(packName(lastOf(kid)), packs.get(kid), () => openScope(kid, true), `Open ${packTitle(kid)}`));
      }
      if (grid.children.length) wrap.appendChild(grid);
      for (const kid of nested) wrap.appendChild(group(kid, false));
      return wrap;
    };

    return group(packBase, true);
  }

  /** Packs tab: the folder tree ("all" mode) or one flat card per pack ("nested"). */
  function renderPackList() {
    if (!el.packList) return;
    el.packList.textContent = "";
    if (el.tabImagesCount) el.tabImagesCount.textContent = String(allFiles.length);

    const keys = sortedPackKeys();
    if (el.tabPacksCount) el.tabPacksCount.textContent = String(keys.length);

    if (PACK_MODE === "all") {
      el.packList.appendChild(buildPackTree());
      return;
    }

    const grid = document.createElement("div");
    grid.className = "col-packgrid";
    for (const key of keys) {
      grid.appendChild(packCard(packTitle(key), packs.get(key), () => openScope(key, true), `Open ${packTitle(key)}`));
    }
    el.packList.appendChild(grid);
  }

  function setTab(name) {
    if (!el.packList) return;
    const showPacks = name === "packs";
    for (const tab of el.tabs) tab.setAttribute("aria-selected", String(tab.dataset.tab === name));
    el.packList.hidden = !showPacks;
    for (const node of [el.toolbar, el.folders, el.stats, el.packs]) if (node) node.hidden = showPacks;
    if (showPacks) hideState();
    else render();
  }

  function renderStats() {
    if (!visible.length) {
      el.stats.textContent = "";
      return;
    }
    const bytes = visible.reduce((sum, file) => sum + file.size, 0);
    const packCount = new Set(visible.map((file) => file.folder)).size;
    const scope = visible.length === allFiles.length ? "" : ` of ${allFiles.length}`;
    const packText = packCount === 1 ? "1 pack" : `${packCount} packs`;
    el.stats.textContent = `${visible.length}${scope} images · ${packText} · ${formatBytes(bytes)}`;
  }

  function buildCard(file, index) {
    const card = document.createElement("button");
    card.type = "button";
    card.className = "col-card";
    card.title = `${file.name} — click to preview`;
    card.addEventListener("click", () => openLightbox(index));

    const media = document.createElement("span");
    media.className = "col-card-media";

    const img = document.createElement("img");
    img.decoding = "async";
    img.draggable = false;
    img.alt = humanName(file);
    // Grid cards use the generated WebP preview (tens of KB) rather than the
    // full-resolution original, which is often several megabytes. The original
    // is only fetched once the lightbox actually opens.
    img.dataset.src = file.thumbUrl || file.url;
    img.addEventListener("load", () => card.classList.add("is-loaded"));
    img.addEventListener("error", () => card.classList.add("is-broken"));
    media.appendChild(img);

    // The first screenful starts downloading immediately at high priority; the
    // rest begin well before they scroll into view (see `watchImages`).
    if (index < EAGER_COUNT) {
      img.fetchPriority = "high";
      img.src = img.dataset.src;
    } else if (imageObserver) {
      imageObserver.observe(img);
    } else {
      img.loading = "lazy";
      img.src = img.dataset.src;
    }

    const overlay = document.createElement("span");
    overlay.className = "col-card-overlay";
    overlay.innerHTML =
      '<svg class="icon icon-sm" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="11" cy="11" r="7"/><path d="m20 20-3.5-3.5"/></svg> Preview';
    media.appendChild(overlay);

    const foot = document.createElement("span");
    foot.className = "col-card-foot";

    const name = document.createElement("span");
    name.className = "col-card-name";
    name.textContent = humanName(file);

    const size = document.createElement("span");
    size.className = "col-card-size";
    size.textContent = formatBytes(file.size);

    foot.append(name, size);
    card.append(media, foot);
    return card;
  }

  function buildPack(folder, files) {
    const section = document.createElement("section");
    section.className = "col-pack";

    const head = document.createElement("div");
    head.className = "col-pack-head";

    const title = document.createElement("h3");
    title.className = "col-pack-title";
    title.textContent = packTitle(folder);

    const meta = document.createElement("span");
    meta.className = "col-pack-meta";
    const bytes = files.reduce((sum, file) => sum + file.size, 0);
    meta.textContent = `${files.length} ${files.length === 1 ? "image" : "images"} · ${formatBytes(bytes)}`;

    head.append(title, meta);

    const grid = document.createElement("div");
    grid.className = "col-grid";

    for (const file of files) {
      grid.appendChild(buildCard(file, visible.length));
      visible.push(file);
    }

    section.append(head, grid);
    return section;
  }

  function render() {
    if (imageObserver) imageObserver.disconnect();
    el.packs.textContent = "";
    visible = [];

    const sorter = sorters[sort] || sorters.name;
    const folders = sortedPackKeys().filter((key) => !activeExact || key === activeFolder);

    const frag = document.createDocumentFragment();

    for (const folder of folders) {
      const files = packs.get(folder).filter(matchesQuery).sort(sorter);
      if (!files.length) continue;
      frag.appendChild(buildPack(folder, files));
    }

    if (!visible.length) {
      showState(
        "empty",
        allFiles.length ? "Nothing matches your filters." : CERT_SCOPE ? "No certificates yet." : "The vault is empty.",
        allFiles.length ? "Try a different search term or pick another pack." : "",
      );
    } else {
      hideState();
      el.packs.appendChild(frag);
    }

    renderStats();
  }

  /* ------------------------------------------------------------------ */
  /* Lightbox                                                            */
  /* ------------------------------------------------------------------ */

  function metaText(file) {
    let text = `${folderLabel(file)} · ${formatBytes(file.size)}${lbDims}`;
    if (shareSession) {
      const msLeft = shareSession.expiresAt - Date.now();
      text +=
        msLeft > 0
          ? ` — shared link, ${Math.max(1, Math.ceil(msLeft / 60000))} min left`
          : " — shared link expired";
    }
    return text;
  }

  function paintMeta(file) {
    el.lbMeta.textContent = metaText(file);
  }

  function startShareTicker() {
    stopShareTicker();
    shareTimer = window.setInterval(() => {
      if (el.lightbox.hidden) return;
      const file = visible[lbPos];
      if (file) paintMeta(file);
    }, 15000);
  }

  function stopShareTicker() {
    if (shareTimer) {
      clearInterval(shareTimer);
      shareTimer = 0;
    }
  }

  function openLightbox(index) {
    lbPos = index;
    if (lbPos < 0 || lbPos >= visible.length) return;

    lastFocused = document.activeElement;
    el.lightbox.hidden = false;
    document.body.classList.add("lb-open");
    paintLightbox();
    el.lbClose.focus({ preventScroll: true });
  }

  function closeLightbox() {
    if (el.lightbox.hidden) return;
    el.lightbox.hidden = true;
    document.body.classList.remove("lb-open");
    lbPos = -1;
    shareSession = null;
    stopShareTicker();
    el.lbImg.removeAttribute("src");
    if (lastFocused && typeof lastFocused.focus === "function") lastFocused.focus({ preventScroll: true });
  }

  function paintLightbox() {
    const file = visible[lbPos];
    if (!file) return;

    lbDims = "";
    el.lbImg.addEventListener(
      "load",
      () => {
        const { naturalWidth: w, naturalHeight: h } = el.lbImg;
        if (w && h) lbDims = ` · ${w}×${h}`;
        paintMeta(file);
      },
      { once: true },
    );

    el.lbImg.src = file.url;
    el.lbImg.alt = humanName(file);
    el.lbName.textContent = humanName(file);
    paintMeta(file);
    el.lbCounter.textContent = `${lbPos + 1} / ${visible.length}`;
  }

  function step(delta) {
    if (!visible.length) return;
    lbPos = (lbPos + delta + visible.length) % visible.length;
    paintLightbox();
  }

  /* ------------------------------------------------------------------ */
  /* Sharing                                                             */
  /* ------------------------------------------------------------------ */

  /** Ask the server for a signed 30-minute link, then copy it. */
  async function shareCurrent() {
    const file = visible[lbPos];
    if (!file || !el.lbShare) return;

    el.lbShare.disabled = true;
    try {
      const response = await fetch(SHARE_ENDPOINT, {
        method: "POST",
        headers: { "Content-Type": "application/json", Accept: "application/json" },
        body: JSON.stringify({ path: file.path }),
      });
      const payload = await response.json().catch(() => ({}));

      if (!response.ok || !payload.url) {
        throw new Error(payload.message || `The server responded with HTTP ${response.status}.`);
      }

      if (CERT_SCOPE) payload.url = payload.url.replace("/collection?", "/certificates?");
      if (await copyText(payload.url)) {
        const minutes = Math.round((payload.ttlSeconds || 1800) / 60);
        toast(`Link copied — it works for ${minutes} minutes.`);
      } else {
        // Clipboard blocked: leave the URL selectable instead of losing it.
        toast(payload.url, "warn", 15000);
      }
    } catch (err) {
      toast(`Could not create a link: ${err?.message || err}`, "warn", 6000);
      console.error(err);
    } finally {
      el.lbShare.disabled = false;
    }
  }

  /* ------------------------------------------------------------------ */
  /* Events                                                              */
  /* ------------------------------------------------------------------ */

  el.search.addEventListener("input", () => {
    query = el.search.value.trim().toLowerCase();
    render();
  });

  el.sort.addEventListener("change", () => {
    sort = el.sort.value;
    render();
  });

  for (const btn of el.viewBtns) btn.addEventListener("click", () => setView(btn.dataset.view));
  {
    let saved = "";
    try {
      saved = localStorage.getItem(VIEW_KEY) || "";
    } catch {
      // ignore
    }
    if (saved === "landscape") setView(saved);
  }

  for (const tab of el.tabs) {
    tab.addEventListener("click", () => {
      tabChosen = true;
      if (tab.dataset.tab === "images") {
        activeFolder = "";
        activeExact = false;
        syncChips();
      }
      setTab(tab.dataset.tab);
    });
  }

  el.lbClose.addEventListener("click", closeLightbox);
  el.lbPrev.addEventListener("click", () => step(-1));
  el.lbNext.addEventListener("click", () => step(1));
  if (el.lbShare) el.lbShare.addEventListener("click", shareCurrent);
  el.lightbox.addEventListener("click", (event) => {
    if (event.target.hasAttribute("data-close")) closeLightbox();
  });

  document.addEventListener("keydown", (event) => {
    if (el.lightbox.hidden) return;
    if (event.key === "Escape") closeLightbox();
    else if (event.key === "ArrowLeft") step(-1);
    else if (event.key === "ArrowRight") step(1);
  });

  // View-only hardening: block the image context menu and drag-to-save.
  // (This is a UX deterrent, not real protection — the proxy never exposes the
  // source URL, and a real paywall belongs on the server.)
  for (const surface of [el.packs, el.lightbox]) {
    surface.addEventListener("contextmenu", (event) => {
      if (event.target.tagName === "IMG") event.preventDefault();
    });
    surface.addEventListener("dragstart", (event) => {
      if (event.target.tagName === "IMG") event.preventDefault();
    });
  }

  /* ------------------------------------------------------------------ */
  /* Boot                                                                */
  /* ------------------------------------------------------------------ */

  /** Work out the container folder, the folders that have subfolders, and each image's pack. */
  function buildPacks() {
    parents = new Set();
    for (const file of allFiles) {
      const parts = (file.folder || "").split("/").filter(Boolean);
      for (let i = 1; i < parts.length; i++) parents.add(parts.slice(0, i).join("/"));
    }

    // A lone top-level folder (e.g. wallpapers/) is only a container, not a pack.
    let base = "";
    for (;;) {
      const tops = new Set(
        allFiles.filter((file) => underFolder(file, base)).map((file) => (file.folder || "").slice(base ? base.length + 1 : 0).split("/")[0]),
      );
      if (tops.size !== 1 || allFiles.some((file) => inFolder(file, base))) break;
      base = base ? `${base}/${[...tops][0]}` : [...tops][0];
    }
    packBase = base;

    const keyOf = (file) => {
      const folder = file.folder || "";
      if (PACK_MODE === "all") return folder;
      for (let f = folder; f && f !== base; f = f.includes("/") ? f.slice(0, f.lastIndexOf("/")) : "") {
        if (parents.has(f)) return f;
      }
      return base;
    };

    packs = new Map();
    for (const file of allFiles) {
      const key = keyOf(file);
      if (!packs.has(key)) packs.set(key, []);
      packs.get(key).push(file);
    }
  }

  function ingest(files) {
    // Presentations have their own page — this view is images only.
    allFiles = (Array.isArray(files) ? files : [])
      .filter(isPreviewable)
      .filter((file) => isCertificate(file) === CERT_SCOPE);

    buildPacks();

    renderChips();
    renderPackList();
    // The collection opens on the Packs tab; certificates have no tab bar.
    if (el.packList && !tabChosen) {
      tabChosen = true;
      setTab(new URLSearchParams(window.location.search).has("share") ? "images" : "packs");
    } else {
      render();
    }
  }

  function setView(view) {
    el.packs.classList.toggle("is-landscape", view === "landscape");
    for (const btn of el.viewBtns) btn.setAttribute("aria-pressed", String(btn.dataset.view === view));
    try {
      localStorage.setItem(VIEW_KEY, view);
    } catch {
      // preference only
    }
  }

  /** Last manifest this browser saw, so a repeat visit paints before the network answers. */
  function readCachedManifest() {
    try {
      const files = JSON.parse(localStorage.getItem(MANIFEST_KEY) || "null");
      return Array.isArray(files) && files.length ? files : null;
    } catch {
      return null;
    }
  }

  function writeCachedManifest(files) {
    try {
      localStorage.setItem(MANIFEST_KEY, JSON.stringify(files));
    } catch {
      // storage full or blocked — the cache is only an optimisation
    }
  }

  /** Returns true when the grid rendered, so the share bootstrap can rely on it. */
  async function load() {
    el.packs.textContent = "";
    el.stats.textContent = "";

    const cached = readCachedManifest();
    if (cached) {
      hideState();
      ingest(cached);
    } else {
      showState("loading", "Loading the vault…", "Fetching the collection index.");
    }

    try {
      const response = await fetch(LIST_ENDPOINT, { headers: { Accept: "application/json" } });
      const payload = await response.json().catch(() => ({}));

      if (!response.ok) {
        const detail =
          payload.message ||
          (response.status === 404
            ? "The API endpoint was not found. Deploy the Cloudflare Pages Function, or run `python dev_server.py` instead of a plain static server."
            : `The server responded with HTTP ${response.status}.`);
        if (cached) return true;
        showState("error", "The collection could not be loaded.", detail);
        return false;
      }

      const fresh = Array.isArray(payload.files) ? payload.files : [];
      const changed = !cached || JSON.stringify(cached) !== JSON.stringify(fresh);
      writeCachedManifest(fresh);
      // Skip the rebuild when nothing changed so painted images don't flicker.
      if (changed) ingest(fresh);
      return true;
    } catch (err) {
      if (cached) return true;
      showState(
        "error",
        "The collection could not be loaded.",
        "Could not reach the API. If you are previewing locally, serve the site with `python dev_server.py` so the bucket proxy is available.",
      );
      console.error(err);
      return false;
    }
  }

  /**
   * `/collection?share=<token>` — resolve the signed token and open that image.
   * Expired links (`410`) get a clear explanation instead of a broken viewer.
   */
  async function openShared() {
    const token = new URLSearchParams(window.location.search).get("share");
    if (!token) return;

    let payload;
    try {
      const response = await fetch(`${SHARE_ENDPOINT}?token=${encodeURIComponent(token)}`, {
        headers: { Accept: "application/json" },
      });
      payload = await response.json().catch(() => ({}));

      if (!response.ok) {
        if (payload.error === "share_expired") {
          showState(
            "error",
            "This shared link has expired.",
            "Shared links last 30 minutes — ask whoever sent it for a fresh one.",
          );
        } else if (payload.error === "not_found") {
          showState(
            "error",
            "That artwork is no longer in the collection.",
            "It may have been moved or deleted from the vault.",
          );
        } else {
          showState("error", "This shared link is not valid.", payload.message || "Ask the sender to create a new link.");
        }
        return;
      }
    } catch (err) {
      showState(
        "error",
        "The shared link could not be opened.",
        "The share API is unreachable. Locally, run `python dev_server.py`.",
      );
      console.error(err);
      return;
    }

    const index = visible.findIndex((file) => file.path === payload.path);
    if (index === -1) {
      showState("error", "That artwork is not available.", "It was not found in the collection index.");
      return;
    }

    shareSession = { expiresAt: Date.parse(payload.expiresAt) || Date.now() };
    startShareTicker();
    openLightbox(index);
  }

  async function boot() {
    if (el.year) el.year.textContent = new Date().getFullYear();
    // The grid is built first so the lightbox has an index to open.
    if (await load()) await openShared();
  }

  boot();
})();
